B=[['拉丁 durus → durare','硬、坚实 → 使变硬；持续、撑住']]
E0=B+[['拉丁 in- + durare → indurare','使坚硬、使坚强'],['古法语 endurer → 中古英语 enduren → endure','忍受、承受；继续存在']]
D=B+[['拉丁 durabilis → 古法语 durable／直接借入','能够持久的'],['英语 durable','耐用、持久的']]
EN=E0[:2]+[['法语 endurer → endurable；或英语 endure + -able','可忍受的；不同资料有借入与英语派生两种分析'],['英语 endurable','能承受、还能忍得了的']]
W=[
E('endure','英 /ɪnˈdjʊə/；美 /ɪnˈdʊr/','忍受、承受；持续存在','压力来了，没有一下子垮掉；时间过去了，仍然撑在那里。前者是人忍苦，后者是某物长久存在。','来自古法语 endurer，远接拉丁 indurare“使硬、使坚强”，由 in- 与 durare 构成。开头 en- 不是英语 end“结束”，所以不是“结束痛苦”。',E0,'endure hardship 是承受艰难；a tradition endures 是传统延续。作“忍受”通常接事情，作“延续”可不接宾语。','endure pain；endure hardship；endure for years；a friendship that endures。','tolerate 偏容忍、接受某事存在；endure 常突出困难和持续承受。last 只说持续，未必带撑过压力的意味。',('The family endured months of uncertainty.','这家人熬过了好几个月的不确定生活。'),('Their friendship endured despite the distance between them.','尽管相隔遥远，他们的友谊一直延续着。'),sources=[S('endure'),K('endure'),O('endure')]),
E('enduring','英 /ɪnˈdjʊərɪŋ/；美 /ɪnˈdʊrɪŋ/','长久的、持久的；正在忍受','一阵热度过去以后，它仍然留着：长期的兴趣、深厚的友谊、没有褪去的影响。','endure 去掉不发音 e，再加 -ing；作现在分词可以表示正在忍受，作形容词常接 endure 的“持续”义。',A(E0,'英语 endure + -ing → enduring','正在承受；作为形容词指长久存在'),'an enduring interest 是长久的兴趣；enduring appeal 是持久吸引力。She is enduring a difficult period 中则是动词进行形式，表示正在熬一段艰难时期。','enduring popularity；enduring appeal；an enduring friendship；an enduring legacy。','endurable 是能够忍受的；enduring 是长久存在或正在忍受的。an enduring friendship 是持久友谊，不是“勉强能忍的友谊”。',('The film has an enduring appeal across generations.','这部电影对几代人都有持久的吸引力。'),('She developed an enduring interest in astronomy as a child.','她小时候形成了对天文学的兴趣，这份兴趣持续了很久。'),sources=[S('enduring'),K('enduring'),O('enduring')]),
E('endurance','英 /ɪnˈdjʊərəns/；美 /ɪnˈdʊrəns/','耐力；忍耐力；持续存在','不是只冲一下，而是能够撑很久：跑步时持续出力，困难里持续坚持，都需要 endurance。','现代对应 endure + -ance；词史也记录法语 endurance 从 endurer 形成的借入路线。早期还有持续存在义，后来忍受困难的能力尤其常用。',E0[:2]+[['法语 endurer → endurance；英语也可分析 endure + -ance','持续存在、承受的状态或能力'],['英语 endurance','耐力、忍耐力']],'physical endurance 是身体耐力；mental endurance 是心理上的持久承受能力；an endurance event 是考验耐力的赛事。','build endurance；test your endurance；an endurance race；beyond endurance。','strength 常说能用多大力；endurance 说能持续多久。patience 强调耐心等待、不急躁，不完全等于身体或心理耐力。',('The long walk tested our endurance more than our speed.','这次长途步行考验的主要是耐力，而不是速度。'),('Weeks of interrupted sleep had pushed her endurance to the limit.','连续几周睡眠被打断，让她的忍耐力到了极限。'),sources=[S('endurance'),K('endurance'),O('endurance')]),
E('endurable','英 /ɪnˈdjʊərəbəl/；美 /ɪnˈdʊrəbəl/','可以忍受的、可以承受的','情况并不好，但还撑得下去，没有超过自己的承受范围。','现代拆作 endure + -able；也有法语 endurable 借入分析。-able 这里是“能够被承受”，不是夸一个人很耐用。',EN,'endurable pain 是还能忍受的疼痛；make a situation endurable 是让处境没那么难熬。它肯定的是能承受，不是舒服。','barely endurable；make something endurable；an endurable situation。','bearable 更口语；endurable 较书面。enjoyable 是愉快的，与“尚能忍受”差得很远。',('A small fan made the heat just endurable.','一台小风扇让酷热勉强变得可以忍受。'),('Her friend’s visits made the long wait more endurable.','朋友来探望，让漫长的等待没那么难熬了。'),sources=[S('endurable'),K('endurable'),O('endurable')]),
E('unendurable','英 /ˌʌnɪnˈdjʊərəbəl/；美 /ˌʌnɪnˈdʊrəbəl/','难以忍受的；让人承受不住的','已经越过“还能撑”的界线：痛苦、噪声、沉默或等待强到让人受不了。','否定 un- + endurable，英语构词；现代重点是“不能被忍受”。早期另有“不能坚持”的用法，不必拿它硬套今天常见的对象。',A(EN,'英语 un- + endurable → unendurable','无法承受、无法忍耐的'),'unendurable noise 是令人难以忍受的噪声；unendurable loneliness 是令人承受不住的孤独。语气强，常用于有情绪力度的叙述。','unendurable pain；unendurable boredom；become unendurable。','unbearable 更常见口语；unendurable 较书面。两者都可能是主观感受，未必在说明一个客观的耐受数值。',('By midnight, the constant drilling had become unendurable.','到了午夜，持续的钻孔声已经让人忍无可忍。'),('The silence felt unendurable after the argument.','争吵之后，那片沉默让人难以承受。'),sources=[S('unendurable'),K('unendurable'),O('unendurable')]),
E('durable','英 /ˈdjʊərəbəl/；美 /ˈdʊrəbəl/','耐用的；持久的','东西经得起用，关系或安排经得起时间，不容易很快坏掉、散掉。','经古法语 durable 或直接借拉丁 durabilis，接 durare“持续、变硬”。现代看起来有 -able，但不是英语 duration 去尾巴得来的。',D,'durable shoes 是耐穿的鞋；a durable agreement 是能长期维持的协议。durable goods 是经济分类中的耐用品，例如家具、家电；复数名词 durables 也可这样用。','durable materials；durable furniture；a durable solution；durable goods。','hard 说硬度，durable 说耐久。柔软的织物也可能很耐用；硬的材料也可能很脆。',('The bag is made from a light but durable fabric.','这个包用轻便而耐用的面料制成。'),('Both sides wanted a durable agreement rather than a brief pause in the dispute.','双方都希望达成能长期维持的协议，而不只是让争端短暂停下来。'),sources=[S('durable'),K('durable'),O('durable')]),
E('durability','英 /ˌdjʊərəˈbɪləti/；美 /ˌdʊrəˈbɪləti/','耐久性；耐用程度','把“能撑多久、不容易坏”作为一种性能来比较。它不是看起来结实，而是经受使用、磨损或时间后仍能保持状态。','现代对应 durable + -ity；历史借古法语 durabilité 或晚期拉丁 durabilitas、durabilitatem，后者从 durabilis 形成，名词有自己的借入路线。',B+[['拉丁 durabilis → durabilitas／durabilitatem','持久的 → 持久耐用这一性质'],['古法语 durabilité／直接拉丁借入 → 英语 durability','耐久性、耐用性']],'test for durability 是测试耐用性；long-term durability 是长期耐久性。比喻中也可讨论制度、联盟或承诺能维持多久。','test durability；improve durability；long-term durability；durability of materials。','durability 关注耐久；reliability 关注运行是否可靠、是否常出错。两者相关，但一件耐久的东西未必从来不出故障。',('The manufacturer tested the hinges for durability.','制造商测试了铰链的耐用性。'),('The crisis raised questions about the durability of the alliance.','危机使人们开始怀疑这个联盟能维持多久。'),sources=[S('durability'),K('durability'),O('durability')]),
E('nondurable','英 /ˌnɒnˈdjʊərəbəl/；美 /ˌnɑːnˈdʊrəbəl/','非耐用的；非耐用品','不是买来反复用很多年，而是较快被消耗、用完或耗损的物品。经济报道里，这是商品类别，不是在骂产品质量差。','non-“非、不” + durable，英语组合；可作形容词，也常用复数名词 nondurables 指非耐用品。',A(D,'英语 non- + durable → nondurable','不持久耐用的；经济学中的非耐用品类别'),'nondurable goods 常包括食品、燃料等。美国 BEA 的统计口径以平均使用寿命少于三年为界；阅读具体统计时要看其采用的定义。','nondurable goods；nondurable consumer goods；spending on nondurables。','durable goods 如家具可长期使用；nondurable goods 消耗较快。优质食品仍属 nondurable，不表示它有制造缺陷。',('Food and fuel are common examples of nondurable goods.','食品和燃料是非耐用品的常见例子。'),('The report separates spending on durable and nondurable products.','报告把耐用品与非耐用品支出分开统计。'),sources=[K('nondurable'),M('nondurable'),'https://www.bea.gov/help/glossary/nondurable-goods']),
E('duration','英 /djuˈreɪʃən/；美 /duˈreɪʃən/','持续时间；时长','从开始到结束，中间这一段有多长。它只量时间，既可以很短，也可以很久，不自带“长期”的意思。','经古法语 duration、duracion，来自中世纪拉丁 duratio、durationem，接 durare“持续”。不能因为有 dur- 就把 duration 全译为耐久。',B+[['中世纪拉丁 duratio／durationem → 古法语 duration／duracion','持续这一状态；持续的时间'],['中古英语 duracioun → duration','时长']],'the duration of a flight 是飞行时长；for the duration of the project 是整个项目持续期间。of short duration 表示持续很短。','the duration of；for the duration；a short duration；of three hours’ duration。','date 是日期或时间点；duration 是时间长度。endurance 是耐力，不是某项活动的计时结果。',('The total duration of the interview was forty minutes.','面试总共持续了四十分钟。'),('The entrance will remain closed for the duration of the repairs.','维修期间，这个入口将一直关闭。'),sources=[S('duration'),K('duration'),O('duration')]),
E('during','英 /ˈdjʊərɪŋ/；美 /ˈdʊrɪŋ/','在……期间','把一段时间当成容器：事情发生在这个时间段里面。它可以发生一次，也可以贯穿全程，要看动词和上下文。','来自中古英语旧动词 duren“持续”的现在分词，远接古法语 durer、拉丁 durare。原来近似“当某段时间持续着”，后来固定为介词；不是英语现代动词 endure 去掉 en-。',B+[['古法语 durer → 中古英语 duren','持续、延续'],['中古英语分词 duryng／durand → during','在某事持续的时候'],['现代英语 during〔介词〕','在某一段时间或事件期间']],'during the meeting 是会议期间；during the night 是夜间。I woke during the night 只说夜里醒过，不表示整夜清醒。during 后通常接名词短语。','during the day；during the meeting；during a visit；during the summer。','during 后接时间事件，如 during the meeting；for 后可接持续长度，如 for two hours；while 常引出句子，如 while we were talking。',('Someone called during the meeting.','开会期间有人打来电话。'),('The shop stayed open during the renovations.','装修期间，这家店一直营业。'),('I read three books during the holiday.','假期里我读了三本书。'),sources=[S('during'),K('during'),O('during')]),
E('duress','英 /djuˈres/；美 /duˈres/','胁迫；强迫；严酷压力','外部压力把选择空间挤没了：人并非自由愿意，而是在威胁或强制下作出行为。','经古法语 duresse、durece，来自拉丁 duritia“坚硬、严酷”，词基 durus。最初的严酷对待后来发展为胁迫义；不是英语 due 与 stress 的混合。',B[:1]+[['拉丁 duritia → 古法语 duresse／durece','坚硬、严酷；严厉对待'],['英语 duress','严酷压力，尤其威胁或强制形成的胁迫']],'under duress 是在胁迫下。一般报道中它也可说极大压力；法律语境有专门判定条件，不能看到普通工作压力就直接等同法律上的胁迫。','under duress；act under duress；a statement made under duress。','stress 可是任何心理、生理压力；duress 常暗示强迫、威胁或选择自由受限。',('She said the statement had been made under duress.','她说，那份陈述是在胁迫下作出的。'),('The article contrasts free consent with decisions made under duress.','文章对比了自由同意与受胁迫作出的决定。'),sources=[S('duress'),K('duress'),O('duress'),'https://www.law.cornell.edu/wex/duress']),
E('dour','英 /dʊə/ 或 /ˈdaʊə/；美 /dʊr/ 或 /ˈdaʊər/','阴沉严厉的；不苟言笑的；令人沉闷的','表情像硬绷着，没有温和笑意；气氛也可以像一张严肃的脸，让人轻松不起来。','经苏格兰语、英格兰北部用法进入通用英语，通常联系拉丁 durus“硬、严厉”；直接借入还是经过中间语言，词源资料有不同分析。',[['拉丁 durus〔通常认为有关〕','硬、严厉'],['苏格兰语及北部英语 dour','严厉、强硬；确切中间路线未定'],['通用英语 dour','阴沉、不苟言笑；沉闷的']],'a dour expression 是阴沉严肃的表情；a dour person 是不易亲近、不爱笑的人；a dour performance 可说一场沉闷的表现。两种常见读法都被词典收录。','a dour expression；a dour manner；a dour mood；a dour match。','serious 可以中性地说认真；dour 往往让人感到阴沉、冷硬或没有乐趣。不要仅凭外表就把它等同 cruel。',('The receptionist’s dour expression softened when she saw the child.','接待员看到孩子后，严肃阴沉的表情柔和了下来。'),('A late goal brought some excitement to an otherwise dour match.','临近结束的一粒进球给原本沉闷的比赛带来了一点刺激。'),sources=[S('dour'),K('dour'),O('dour')]),
E('durum','英 /ˈdjʊərəm/；美 /ˈdʊrəm/','硬粒小麦、杜兰小麦','这里“硬”直接回到谷粒：一种常用来制作意大利面的硬粒小麦，名字取自拉丁语“硬的”。','借新拉丁植物名称中的 durum，词形是拉丁 durus 的中性形式。现代常作 durum wheat 的简称；不是所有口感硬的麦子都能随意叫 durum。',[['拉丁 durus；中性 durum','硬的'],['新拉丁植物名称中的 durum → 英语 durum wheat／durum','硬粒小麦名称；用于食物与原料标签']],'durum wheat semolina 是硬粒小麦粗粒粉，常见于意大利面包装。durum 指小麦类型，semolina 指相应的粗粒研磨产品，两个词不能直接互换。','durum wheat；durum semolina；pasta made from durum。','wheat 是小麦总称，durum 是其中一类。durable 虽同根，说的是耐用性；durum 在食品语境不是“耐用的小麦”。',('The label says the pasta is made from durum wheat semolina.','标签写着这款意大利面由硬粒小麦粗粒粉制成。'),('The mill processes durum for pasta manufacturers.','这家磨坊为意大利面生产商加工硬粒小麦。'),sources=[S('durum'),K('durum'),M('durum')]),
]
EXCLUDE={w:'按用户要求暂略：主要用于专门医学、煤岩或木材学、语法术语，或已属罕见旧式派生；本页保留通用阅读词。' for w in ['subdural','dural','durance','dure','induration','durative','durain','duramen','durancy','durity','durous','endurant','indurate','obduration','perdurable','perdurance','perdure','dura']}
ROOT=dict(id='C0353',meaning='硬；坚实；持续、撑住',core='拉丁 durus 是硬、坚实。材料硬实所以经得起使用，人撑住压力所以能够忍受，事物撑过时间所以能够延续。',image='durus“硬” → durable 耐用、durability 耐久；indurare“使硬” → endure 承受、endurance 耐力；durare“持续” → duration 时长、during 在期间。',intro='同一个“撑得住”可以描述材料、人的承受力和时间上的延续。另一边，硬也可能是态度冷硬或对待严酷，于是有 dour、duress、obdurate。',forms='durare 既有使变硬，也有持续义。duration、durability、duress 各有拉丁、法语名词借入路线；during 原来是旧动词 duren 的分词。endure 的 en- 来自法语，不是英语 end。',branches=[['承受与延续','endure, enduring, endurance, endurable, unendurable'],['耐用与商品分类','durable, durability, nondurable'],['时间长度与时间范围','duration, during'],['严酷、冷硬与固执','duress, dour, obdurate, obduracy'],['食材的硬粒特征','durum']],contrasts='durable 是耐用，endurable 是能忍受，enduring 是长久存在。duration 是时长，endurance 是耐力。durum 是具体小麦类型。硬的意象只是理解桥梁，不代表所有词都能互换。',practice='A durable bag can endure years of use. 耐用的包能经得起多年使用。再比较：during the journey 是旅途中，the duration of the journey 是旅程的时长。',words=[],exclude=EXCLUDE)
